:root {
  /* Quantum Kaleidoscope Theme - iridescent prisms and motion-responsive tilt */
  --bg-primary: #050510;
  --bg-alt: #0e0a1f;
  --bg-hover: #160f2f;
  --text-primary: #f6f9ff;
  --text-secondary: #c6d2ff;
  --border: #7af0ff;
  --accent: #f25ce0;
  --accent-hover: #f998ff;
  --glass: rgba(255, 255, 255, 0.06);
}

body {
  background: radial-gradient(circle at 15% 20%, rgba(122, 240, 255, 0.15), transparent 30%),
              radial-gradient(circle at 80% 60%, rgba(242, 92, 224, 0.18), transparent 30%),
              linear-gradient(135deg, #050510 0%, #0e0a1f 50%, #050510 100%);
  color: var(--text-primary);
}

.card {
  background: var(--glass);
  border: 1px solid rgba(122, 240, 255, 0.4);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45), 0 0 1px 1px rgba(122, 240, 255, 0.2);
  backdrop-filter: blur(10px) saturate(140%);
  transform: perspective(600px) rotateX(var(--tilt-x, 0deg)) rotateY(var(--tilt-y, 0deg));
  transition: transform 0.1s ease-out, border-color 0.2s, box-shadow 0.2s;
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  inset: -20%;
  background: conic-gradient(from 120deg, #7af0ff, #f25ce0, #9b8cff, #7af0ff);
  filter: blur(36px);
  opacity: 0.28;
  animation: prismShift 10s linear infinite;
  pointer-events: none;
}

.card:hover {
  border-color: var(--accent);
  box-shadow: 0 22px 60px rgba(242, 92, 224, 0.35), 0 0 1px 1px rgba(242, 92, 224, 0.3);
}

.card-title {
  background: linear-gradient(90deg, #7af0ff, #f25ce0, #7af0ff);
  -webkit-background-clip: text;
  color: transparent;
  letter-spacing: 1px;
  text-transform: uppercase;
}

@keyframes prismShift {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
